using System.Collections.ObjectModel;
using CommunityToolkit.Mvvm.ComponentModel;

namespace VisualRelay.App.ViewModels;

public partial class MainWindowViewModel
{
    public sealed partial class ModelCostRow : ObservableObject
    {
        [ObservableProperty]
        private string _modelKey = string.Empty;

        [ObservableProperty]
        private bool _isActive;

        [ObservableProperty]
        private bool _isPriced;

        /// <summary>Tier badges for active cards, ordered by
        /// <see cref="MainWindowViewModel.TierOrder"/>.</summary>
        public ObservableCollection<string> TierBadges { get; } = [];

        // Base rate display strings — preformatted invariant-culture strings.
        // No XAML StringFormat is used anywhere for these values.

        [ObservableProperty]
        private string _inputDisplay = string.Empty;

        [ObservableProperty]
        private string _outputDisplay = string.Empty;

        [ObservableProperty]
        private string _cachedInputDisplay = string.Empty;

        [ObservableProperty]
        private string _cacheWriteDisplay = string.Empty;

        // ── Time-of-day windows ────────────────────────────────────────

        [ObservableProperty]
        private bool _hasWindows;

        public ObservableCollection<ModelCostWindowRow> Windows { get; } = [];
    }

    public sealed partial class ModelCostWindowRow : ObservableObject
    {
        /// <summary>Local-time window header, e.g. "6:00 PM – 9:00 PM your time — 2× peak pricing".</summary>
        [ObservableProperty]
        private string _headline = string.Empty;

        /// <summary>Source-time note, e.g. "(9:00 AM – 12:00 PM in Asia/Shanghai)".
        /// Empty when timezone conversion fails.</summary>
        [ObservableProperty]
        private string _sourceNote = string.Empty;

        // Peak rate display strings — preformatted invariant-culture strings.

        [ObservableProperty]
        private string _peakInputDisplay = string.Empty;

        [ObservableProperty]
        private string _peakOutputDisplay = string.Empty;

        [ObservableProperty]
        private string _peakCachedInputDisplay = string.Empty;

        [ObservableProperty]
        private string _peakCacheWriteDisplay = string.Empty;
    }
}

using System.Collections.ObjectModel;
using System.Globalization;
using CommunityToolkit.Mvvm.ComponentModel;
using VisualRelay.Core.Configuration;
using VisualRelay.Core.Costs;

namespace VisualRelay.App.ViewModels;

public partial class MainWindowViewModel
{
    [ObservableProperty]
    private ObservableCollection<ModelCostRow> _modelCostRows = [];

    /// <summary>Fixed ordering for tier badges so cards sort and display consistently.</summary>
    private static readonly string[] TierOrder =
        ["cheap", "balanced", "frontier", "vision", "claude", "fallback"];

    /// <summary>
    /// Rebuild the "Cost Per LLM Model" card list from concrete pricing data
    /// and the given tier→model assignments. When <paramref name="tierAssignments"/>
    /// is null, the default resolution from <see cref="BackendConfigGenerator.DefaultTierResolution"/>
    /// is used. The card set is the union of <see cref="RelayPricing.Default"/> keys
    /// and the assignment values, so an override pointing a tier at a model with no
    /// pricing entry still yields a card (marked unpriced).
    /// </summary>
    public void PopulateModelCostRows(IReadOnlyDictionary<string, string>? tierAssignments = null)
    {
        var assignments = tierAssignments ?? BackendConfigGenerator.DefaultTierResolution;

        // Build reverse map: concrete model → ordered list of tier badges.
        var badgesByModel = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var tier in TierOrder)
        {
            if (!assignments.TryGetValue(tier, out var model))
                continue;
            if (!badgesByModel.TryGetValue(model, out var list))
                badgesByModel[model] = list = [];
            list.Add(tier);
        }

        // Card set: union of pricing keys and assignment values.
        var modelKeys = new HashSet<string>(RelayPricing.Default.Keys, StringComparer.Ordinal);
        foreach (var (_, model) in assignments)
            modelKeys.Add(model);

        var rows = new List<ModelCostRow>();
        foreach (var modelKey in modelKeys)
        {
            var hasPricing = RelayPricing.Default.TryGetValue(modelKey, out var pricing);
            var badges = badgesByModel.GetValueOrDefault(modelKey, []);
            var isActive = badges.Count > 0;
            var isPriced = hasPricing;

            var row = new ModelCostRow
            {
                ModelKey = modelKey,
                IsActive = isActive,
                IsPriced = isPriced,
                HasWindows = hasPricing && pricing!.Windows is { Count: > 0 },
            };

            foreach (var badge in badges)
                row.TierBadges.Add(badge);

            if (hasPricing)
            {
                var p = pricing!;
                row.InputDisplay = FormatRate(p.Input);
                row.OutputDisplay = FormatRate(p.Output);
                row.CachedInputDisplay = FormatRateRelativeToInput(p.EffectiveCachedInput, p.Input);
                row.CacheWriteDisplay = FormatRateRelativeToInput(p.EffectiveCacheWrite, p.Input);

                if (p.Windows is { Count: > 0 })
                {
                    foreach (var window in p.Windows)
                    {
                        var m = window.Multiplier;
                        var windowRow = new ModelCostWindowRow();

                        BuildWindowHeadlineAndNote(window, out var headline, out var sourceNote);
                        windowRow.Headline = headline;
                        windowRow.SourceNote = sourceNote;
                        windowRow.PeakInputDisplay = FormatRate(p.Input * m);
                        windowRow.PeakOutputDisplay = FormatRate(p.Output * m);
                        windowRow.PeakCachedInputDisplay = FormatRateRelativeToInput(p.EffectiveCachedInput * m, p.Input * m);
                        windowRow.PeakCacheWriteDisplay = FormatRateRelativeToInput(p.EffectiveCacheWrite * m, p.Input * m);

                        row.Windows.Add(windowRow);
                    }
                }
            }

            rows.Add(row);
        }

        // Sort: models with badges first (by first badge's TierOrder index),
        // then unassigned models by ordinal model name.
        int TierIndex(string? badge) =>
            badge is null ? int.MaxValue : Array.IndexOf(TierOrder, badge);

        rows.Sort((a, b) =>
        {
            var aBadge = a.TierBadges.Count > 0 ? a.TierBadges[0] : null;
            var bBadge = b.TierBadges.Count > 0 ? b.TierBadges[0] : null;
            var cmp = TierIndex(aBadge).CompareTo(TierIndex(bBadge));
            if (cmp != 0) return cmp;
            return string.CompareOrdinal(a.ModelKey, b.ModelKey);
        });

        ModelCostRows.Clear();
        foreach (var row in rows)
            ModelCostRows.Add(row);
    }

    // ── Formatting helpers (invariant culture, no XAML StringFormat) ────

    /// <summary>Format a rate in USD per million tokens with invariant-culture
    /// precision. Uses the shortest fixed-point form; 0.003625 renders as "$0.003625".</summary>
    private static string FormatRate(double rate) =>
        "$" + rate.ToString("0.######", CultureInfo.InvariantCulture) + " per 1M tokens";

    /// <summary>Format a rate and annotate when the effective rate equals the
    /// base input rate, covering both null-fallback and explicit equality.</summary>
    private static string FormatRateRelativeToInput(double effective, double input) =>
        effective == input ? FormatRate(effective) + " (same as input)" : FormatRate(effective);

    // ── Time-window formatting ──────────────────────────────────────────

    /// <summary>Build the Headline and SourceNote strings from a RateWindow.
    /// Headline uses local-time with literal "your time"; SourceNote uses
    /// source times with the IANA timezone ID. Never emits platform timezone
    /// identifiers like PST8PDT.</summary>
    private static void BuildWindowHeadlineAndNote(
        RateWindow window, out string headline, out string sourceNote)
    {
        var sourceStart = window.StartLocal.ToString("h:mm tt", CultureInfo.InvariantCulture);
        var sourceEnd = window.EndLocal.ToString("h:mm tt", CultureInfo.InvariantCulture);
        var multiplierLabel = window.Multiplier.ToString("0.#", CultureInfo.InvariantCulture) + "× peak pricing";

        sourceNote = $"({sourceStart} – {sourceEnd} in {window.TimeZoneId})";

        try
        {
            var sourceTz = TimeZoneInfo.FindSystemTimeZoneById(window.TimeZoneId);
            var today = DateOnly.FromDateTime(DateTime.UtcNow);
            var sourceStartDt = today.ToDateTime(window.StartLocal, DateTimeKind.Unspecified);
            var sourceEndDt = today.ToDateTime(window.EndLocal, DateTimeKind.Unspecified);
            var utcStart = TimeZoneInfo.ConvertTimeToUtc(sourceStartDt, sourceTz);
            var utcEnd = TimeZoneInfo.ConvertTimeToUtc(sourceEndDt, sourceTz);
            var localStart = TimeZoneInfo.ConvertTimeFromUtc(utcStart, TimeZoneInfo.Local);
            var localEnd = TimeZoneInfo.ConvertTimeFromUtc(utcEnd, TimeZoneInfo.Local);
            var localStartStr = TimeOnly.FromDateTime(localStart).ToString("h:mm tt", CultureInfo.InvariantCulture);
            var localEndStr = TimeOnly.FromDateTime(localEnd).ToString("h:mm tt", CultureInfo.InvariantCulture);
            headline = $"{localStartStr} – {localEndStr} your time — {multiplierLabel}";
        }
        catch
        {
            // Timezone conversion failed — use source times in place of local.
