using System.Globalization;
using System.Text.RegularExpressions;
using VisualRelay.App.ViewModels;
using VisualRelay.Core.Configuration;
using VisualRelay.Core.Costs;

namespace VisualRelay.Tests;

public sealed class CostPerModelTests
{
    // ── No tier aliases as card keys ────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_NoModelKeyIsATierAlias()
    {
        var tierAliases = new HashSet<string>(
            BackendConfigGenerator.DefaultTierResolution.Keys, StringComparer.Ordinal);

        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        foreach (var row in vm.ModelCostRows)
            Assert.DoesNotContain(row.ModelKey, tierAliases);
    }

    [Fact]
    public void PopulateModelCostRows_NoDuplicateModelKeys()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var keys = vm.ModelCostRows.Select(r => r.ModelKey).ToList();
        Assert.Equal(keys.Distinct(StringComparer.Ordinal).Count(), keys.Count);
    }

    // ── Default resolution badges ───────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_DefaultBadges()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var cheapCard = vm.ModelCostRows.First(r => r.TierBadges.Contains("cheap"));
        Assert.Equal("deepseek-v4-flash", cheapCard.ModelKey);
        Assert.True(cheapCard.IsActive);

        var balancedCard = vm.ModelCostRows.First(r => r.TierBadges.Contains("balanced"));
        Assert.Equal("deepseek-v4-pro", balancedCard.ModelKey);
        Assert.True(balancedCard.IsActive);

        var frontierCard = vm.ModelCostRows.First(r => r.TierBadges.Contains("frontier"));
        Assert.Equal("glm-5.2", frontierCard.ModelKey);
        Assert.True(frontierCard.IsActive);

        var visionCard = vm.ModelCostRows.First(r => r.TierBadges.Contains("vision"));
        Assert.Equal("hf-qwen3-vl-235b", visionCard.ModelKey);
        Assert.True(visionCard.IsActive);

        // kimi-k2 and gpt-5 have no badge and are inactive.
        var kimi = vm.ModelCostRows.Single(r => r.ModelKey == "kimi-k2");
        Assert.Empty(kimi.TierBadges);
        Assert.False(kimi.IsActive);

        var gpt5 = vm.ModelCostRows.Single(r => r.ModelKey == "gpt-5");
        Assert.Empty(gpt5.TierBadges);
        Assert.False(gpt5.IsActive);
    }

    // ── Ordering ────────────────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_BadgedCardsPrecedeUnbadged()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var foundUnbadged = false;
        foreach (var row in vm.ModelCostRows)
        {
            if (row.TierBadges.Count == 0)
                foundUnbadged = true;
            else
                Assert.False(foundUnbadged, $"badged card '{row.ModelKey}' appears after unbadged cards");
        }
    }

    [Fact]
    public void PopulateModelCostRows_FirstCardIsCheapModel()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        Assert.Equal("deepseek-v4-flash", vm.ModelCostRows[0].ModelKey);
        Assert.Contains("cheap", vm.ModelCostRows[0].TierBadges);
    }

    // ── Explicit assignments ────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_ExplicitAssignmentWins()
    {
        var assignments = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["cheap"] = "kimi-k2",
        };

        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows(assignments);

        // kimi-k2 now carries the cheap badge.
        var kimi = vm.ModelCostRows.Single(r => r.ModelKey == "kimi-k2");
        Assert.Contains("cheap", kimi.TierBadges);
        Assert.True(kimi.IsActive);

        // deepseek-v4-flash is now unbadged.
        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        Assert.Empty(flash.TierBadges);
        Assert.False(flash.IsActive);
    }

    // ── Unpriced assignment ─────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_UnpricedAssignmentYieldsCard()
    {
        var assignments = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["vision"] = "hf-qwen3-vl-30b",
        };

        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows(assignments);

        var card = vm.ModelCostRows.Single(r => r.ModelKey == "hf-qwen3-vl-30b");
        Assert.Contains("vision", card.TierBadges);
        Assert.False(card.IsPriced, "unpriced model must have IsPriced=false");
        Assert.True(card.IsActive);
        Assert.Empty(card.InputDisplay); // no pricing strings set
    }

    // ── CachedInput / CacheWrite display ────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_CachedInputDisplay_NullFallsBackToInput()
    {
        // hf-qwen3-coder-next has null CachedInput → EffectiveCachedInput == Input (0.30).
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var row = vm.ModelCostRows.Single(r => r.ModelKey == "hf-qwen3-coder-next");
        Assert.Equal("$0.3 per 1M tokens (same as input)", row.CachedInputDisplay);
    }

    [Fact]
    public void PopulateModelCostRows_CacheWriteDisplay_ExplicitEqualsInput_Annotated()
    {
        // deepseek-v4-flash: CacheWrite = 0.14 == Input.
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var row = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        Assert.EndsWith("(same as input)", row.CacheWriteDisplay, StringComparison.Ordinal);
        Assert.StartsWith("$0.14", row.CacheWriteDisplay, StringComparison.Ordinal);
    }

    [Fact]
    public void PopulateModelCostRows_CacheWriteDisplay_ExplicitDifferent_NoAnnotation()
    {
        // claude-opus-1m: CacheWrite = 6.25, Input = 5.0 → different.
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var row = vm.ModelCostRows.Single(r => r.ModelKey == "claude-opus-1m");
        Assert.Equal("$6.25 per 1M tokens", row.CacheWriteDisplay);
        Assert.DoesNotContain("same as input", row.CacheWriteDisplay, StringComparison.Ordinal);
    }

    // ── Peak rows ───────────────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_PeakCachedInput_UsesEffectiveNotZero()
    {
        // deepseek-v4-flash: CachedInput = 0.0028, Input = 0.14.
        // Peak multiplier 2× → PeakCachedInputDisplay = $0.0056.
        // The old bug used (CachedInput ?? 0) → would show $0.
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        var w = flash.Windows[0];
        Assert.StartsWith("$0.0056", w.PeakCachedInputDisplay, StringComparison.Ordinal);
    }

    [Fact]
    public void PopulateModelCostRows_PeakCacheWrite_AnnotatedWhenEqualsInput()
    {
        // deepseek-v4-flash: CacheWrite=0.14==Input → peak CacheWrite annotated.
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        var w = flash.Windows[0];
        Assert.EndsWith("(same as input)", w.PeakCacheWriteDisplay, StringComparison.Ordinal);
    }

    // ── Culture safety ──────────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_CultureSafe_RatesUseDotNotComma()
    {
        var originalCulture = CultureInfo.CurrentCulture;
        try
        {
            CultureInfo.CurrentCulture = new CultureInfo("de-DE");

            var vm = new MainWindowViewModel();
            vm.PopulateModelCostRows();

            // A fractional rate must contain a dot, not a comma.
            var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
            Assert.Contains(".", flash.InputDisplay, StringComparison.Ordinal);
            Assert.DoesNotContain(",", flash.InputDisplay, StringComparison.Ordinal);
        }
        finally
        {
            CultureInfo.CurrentCulture = originalCulture;
        }
    }

    // ── Window headline and source note ─────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_WindowHeadline_Matches12HourPattern()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        var w = flash.Windows[0];

        // Headline: "6:00 PM – 9:00 PM your time — 2× peak pricing" (or similar for local TZ).
        Assert.Matches(
            @"^\d{1,2}:\d{2} [AP]M – \d{1,2}:\d{2} [AP]M your time — 2× peak pricing$",
            w.Headline);
    }

    [Fact]
    public void PopulateModelCostRows_WindowSourceNote_IsCorrect()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        var w = flash.Windows[0];

        Assert.Equal("(9:00 AM – 12:00 PM in Asia/Shanghai)", w.SourceNote);
    }

    [Fact]
    public void PopulateModelCostRows_WindowHeadline_NeverContainsPlatformTimezoneId()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var flash = vm.ModelCostRows.Single(r => r.ModelKey == "deepseek-v4-flash");
        foreach (var w in flash.Windows)
        {
            Assert.DoesNotContain(TimeZoneInfo.Local.Id, w.Headline, StringComparison.Ordinal);
            Assert.DoesNotContain("PST8PDT", w.Headline, StringComparison.Ordinal);
        }
    }

    // ── Idempotency ─────────────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_IsIdempotent()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();
        var count = vm.ModelCostRows.Count;

        vm.PopulateModelCostRows();
        Assert.Equal(count, vm.ModelCostRows.Count);
    }

    [Fact]
    public void PopulateModelCostRows_Parameterless_UsesDefaultResolution()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();
        var cards1 = vm.ModelCostRows.Select(r => r.ModelKey).OrderBy(k => k, StringComparer.Ordinal).ToList();

        var vm2 = new MainWindowViewModel();
        vm2.PopulateModelCostRows(null);
        var cards2 = vm2.ModelCostRows.Select(r => r.ModelKey).OrderBy(k => k, StringComparer.Ordinal).ToList();

        Assert.Equal(cards1, cards2);
    }

    // ── IsPriced for priced vs unpriced cards ───────────────────────────

    [Fact]
    public void PopulateModelCostRows_AllDefaultCards_ArePriced()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        // Every card from the default resolution should be priced
        // (all resolution models have pricing entries).
        Assert.All(vm.ModelCostRows, r => Assert.True(r.IsPriced, $"'{r.ModelKey}' should be priced"));
    }

    // ── Vision badge ────────────────────────────────────────────────────

    [Fact]
    public void PopulateModelCostRows_VisionBadgeOnHfQwen3Vl235b()
    {
        var vm = new MainWindowViewModel();
        vm.PopulateModelCostRows();

        var visionCard = vm.ModelCostRows.Single(r => r.ModelKey == "hf-qwen3-vl-235b");
        Assert.Contains("vision", visionCard.TierBadges);
        Assert.True(visionCard.IsActive);
    }
}

using VisualRelay.Core.Configuration;
using VisualRelay.Core.Costs;
using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

public sealed class BackendConfigGeneratorAliasConsistencyTests
{
    // ── Cross-file tier-name consistency ────────────────────────────────

    /// <summary>
    /// (1) Every tier alias in <see cref="BackendConfigGenerator.Chains"/> has a
    ///     <see cref="BackendConfigGenerator.DefaultTierResolution"/> entry.
    /// (2) Every <see cref="DefaultTierResolution"/> value has a
    ///     <see cref="RelayPricing.Default"/> entry.
    /// (3) No tier alias appears as a pricing key (concrete models only).
    /// (4) The balanced/cheap tier-alias names must match the swival profile.
    /// </summary>
    [Fact]
    public void TierAliasNames_AreConsistentAcrossBackendConfigPricingAndSwivalProfile()
    {
        var tierAliases = BackendConfigGenerator.Chains.Keys.ToHashSet(StringComparer.Ordinal);

        // 1. Every tier alias must have a DefaultTierResolution entry.
        foreach (var tier in tierAliases)
        {
            Assert.True(
                BackendConfigGenerator.DefaultTierResolution.ContainsKey(tier),
                $"tier '{tier}' missing from DefaultTierResolution");
        }

        // 2. Every DefaultTierResolution value must have a RelayPricing.Default entry.
        foreach (var (tier, concrete) in BackendConfigGenerator.DefaultTierResolution)
        {
            Assert.True(
                RelayPricing.Default.ContainsKey(concrete),
                $"DefaultTierResolution['{tier}'] = '{concrete}' missing from RelayPricing.Default");
        }

        // 3. Pricing keys must contain no tier alias.
        var pricingKeys = RelayPricing.Default.Keys.ToHashSet(StringComparer.Ordinal);
        foreach (var tier in tierAliases)
        {
            Assert.DoesNotContain(tier, pricingKeys);
        }

        // 4. Swival profile tier-name assertions (keep unchanged).
        var swivalModelValues = BackendConfigGeneratorTestHelpers.ParseSwivalProfileModelValues(
            SwivalProfileSession.DefaultToml);

        var balancedTier = swivalModelValues["balanced"];
        var cheapTier = swivalModelValues["cheap"];

        Assert.DoesNotContain("-kimi", balancedTier, StringComparison.Ordinal);
        Assert.DoesNotContain("-kimi", cheapTier, StringComparison.Ordinal);
        Assert.Equal("balanced", balancedTier);
        Assert.Equal("cheap", cheapTier);

        Assert.Contains(balancedTier, tierAliases);
        Assert.Contains(cheapTier, tierAliases);
    }
}

