    {
        // Identical token stats, model "cheap" vs "deepseek-v4-flash" → same cost.
        using var cheapDoc = JsonDocument.Parse(
            """
            {
              "model": "cheap",
              "result": { "answer": "abcdefghijkl" },
              "stats": {
                "total_llm_time_s": 1.5,
                "total_tool_time_s": 0.25,
                "prompt_cache": { "cached_tokens": 100 }
              },
              "timeline": [
